+
+    if (!bufferSize) {
+        return NULL;
+    }
+
+    associatedExe = (char*)g_malloc(bufferSize);
+    hr = AssocQueryStringA(
+        ASSOCF_INIT_IGNOREUNKNOWN,
+        ASSOCSTR_COMMAND, // ASSOCSTR_EXECUTABLE might miss arguments
+        fileExtension,
+        "open",
+        associatedExe,
+        &bufferSize
+    );
+
+    if (!SUCCEEDED(hr)) {
+        g_free(associatedExe);
+        return NULL;
+    }
+
+    return associatedExe;
+}
